#!/usr/bin/env python3
"""
Analyze USGS streamflow data to find stations that experienced flooding
during April 1-7, 2025.

USGS defines flooding based on flood stage thresholds. We'll fetch:
1. Daily streamflow values for the date range
2. Flood stage information from the USGS Flood Event Viewer / NWIS

For each station, flooding occurs when streamflow exceeds the flood stage threshold.
"""

import requests
import csv
from datetime import datetime, timedelta
from collections import defaultdict

# Read station IDs
with open('/root/data/michigan_stations.txt', 'r') as f:
    stations = [line.strip() for line in f if line.strip()]

print(f"Found {len(stations)} stations to analyze")

# Date range
start_date = "2025-04-01"
end_date = "2025-04-07"

# USGS NWIS API endpoints
# Parameter code 00060 = Discharge (streamflow) in cubic feet per second
# Parameter code 00065 = Gage height in feet

# First, get the flood stage thresholds for each station from the Flood Event Viewer API
# The USGS provides action/minor/moderate/major flood stages

flood_stages = {}

print("Fetching flood stage thresholds...")

# Try to get flood stage data from USGS/NWS flood thresholds
# Using the USGS Flood Event Viewer API
for station in stations:
    try:
        # USGS provides flood stages via their API
        url = f"https://waterwatch.usgs.gov/webservices/floodstage?site_no={station}&format=json"
        resp = requests.get(url, timeout=30)
        if resp.status_code == 200:
            data = resp.json()
            if 'sites' in data and len(data['sites']) > 0:
                site = data['sites'][0]
                # Get action stage (lowest flood threshold)
                if 'action_stage' in site and site['action_stage']:
                    flood_stages[station] = float(site['action_stage'])
                    print(f"  Station {station}: action stage = {flood_stages[station]} ft")
    except Exception as e:
        pass

print(f"\nFound flood stage data for {len(flood_stages)} stations")

# If we couldn't get flood stages from the first API, try alternative approach
# using the National Weather Service flood stages
if len(flood_stages) < len(stations) / 2:
    print("\nTrying alternative flood stage source...")
    # Use USGS waterservices with statistics
    for station in stations:
        if station in flood_stages:
            continue
        try:
            # Get percentile data which can indicate high flow conditions
            url = f"https://waterservices.usgs.gov/nwis/stat/?format=json&sites={station}&statReportType=daily&statTypeCd=p80"
            resp = requests.get(url, timeout=30)
            if resp.status_code == 200:
                data = resp.json()
                # Process statistics if available
                pass
        except:
            pass

# Now fetch gage height data for the date range to compare against flood stages
print("\nFetching gage height data for April 1-7, 2025...")

# Build URL for all stations at once (more efficient)
stations_str = ",".join(stations)

# Get daily values for gage height (parameter 00065)
url = f"https://waterservices.usgs.gov/nwis/dv/?format=json&sites={stations_str}&startDT={start_date}&endDT={end_date}&parameterCd=00065&siteStatus=all"

print(f"Fetching from USGS NWIS...")

gage_data = {}
try:
    resp = requests.get(url, timeout=120)
    if resp.status_code == 200:
        data = resp.json()
        if 'value' in data and 'timeSeries' in data['value']:
            for ts in data['value']['timeSeries']:
                site_code = ts['sourceInfo']['siteCode'][0]['value']
                if 'values' in ts and len(ts['values']) > 0:
                    values_list = ts['values'][0].get('value', [])
                    if site_code not in gage_data:
                        gage_data[site_code] = {}
                    for v in values_list:
                        date = v['dateTime'][:10]
                        try:
                            gage_data[site_code][date] = float(v['value'])
                        except:
                            pass
        print(f"  Retrieved gage height data for {len(gage_data)} stations")
except Exception as e:
    print(f"  Error fetching gage height data: {e}")

# Also try to get flood data from USGS flood event data
print("\nFetching flood event data...")

# Use WaterWatch current conditions which includes flood status
flood_conditions = {}
try:
    url = "https://waterwatch.usgs.gov/webservices/realtime?region=mi&format=json"
    resp = requests.get(url, timeout=60)
    if resp.status_code == 200:
        data = resp.json()
        # Process flood status data
        if 'sites' in data:
            for site in data['sites']:
                site_no = site.get('site_no', '')
                if site_no in stations:
                    flood_status = site.get('flood_status', '')
                    if flood_status:
                        flood_conditions[site_no] = flood_status
except Exception as e:
    print(f"  Error: {e}")

# For historical data (April 2025), we need to compare gage heights to flood stages
# Let's also fetch instantaneous values which might give us more data
print("\nFetching instantaneous values for better coverage...")

url = f"https://waterservices.usgs.gov/nwis/iv/?format=json&sites={stations_str}&startDT={start_date}&endDT={end_date}&parameterCd=00065&siteStatus=all"

iv_data = {}
try:
    resp = requests.get(url, timeout=120)
    if resp.status_code == 200:
        data = resp.json()
        if 'value' in data and 'timeSeries' in data['value']:
            for ts in data['value']['timeSeries']:
                site_code = ts['sourceInfo']['siteCode'][0]['value']
                if 'values' in ts and len(ts['values']) > 0:
                    values_list = ts['values'][0].get('value', [])
                    if site_code not in iv_data:
                        iv_data[site_code] = {}
                    for v in values_list:
                        date = v['dateTime'][:10]
                        try:
                            val = float(v['value'])
                            # Keep the maximum value per day
                            if date not in iv_data[site_code] or val > iv_data[site_code][date]:
                                iv_data[site_code][date] = val
                        except:
                            pass
        print(f"  Retrieved instantaneous data for {len(iv_data)} stations")
except Exception as e:
    print(f"  Error: {e}")

# Merge gage data
for site, dates in iv_data.items():
    if site not in gage_data:
        gage_data[site] = {}
    for date, val in dates.items():
        if date not in gage_data[site] or val > gage_data[site][date]:
            gage_data[site][date] = val

# Now try to get flood stage data from another USGS source
print("\nFetching flood stage data from USGS site service...")

# Get site metadata which may include flood stage info
for station in stations:
    if station in flood_stages:
        continue
    try:
        url = f"https://waterservices.usgs.gov/nwis/site/?format=rdb&sites={station}&siteOutput=expanded"
        resp = requests.get(url, timeout=30)
        # The flood stage is not in the basic site service, but let's try the WaterWatch API
    except:
        pass

# Alternative: Use NWS flood stage data
print("\nFetching NWS flood stage data...")
try:
    # NWS Advanced Hydrologic Prediction Service provides flood stages
    # mapped to USGS gage IDs
    url = "https://water.weather.gov/ahps2/hydrograph_to_xml.php?gage_list=all&output=xml"
    # This would be complex to parse, so let's use a simpler approach
except:
    pass

# Let's try the USGS WaterWatch flood stage service with all stations at once
print("\nTrying batch flood stage fetch...")
try:
    url = f"https://waterwatch.usgs.gov/webservices/floodstage?site_no={stations_str}&format=json"
    resp = requests.get(url, timeout=60)
    if resp.status_code == 200:
        data = resp.json()
        if 'sites' in data:
            for site in data['sites']:
                site_no = site.get('site_no', '')
                action = site.get('action_stage')
                minor = site.get('minor_stage')
                moderate = site.get('moderate_stage')
                major = site.get('major_stage')
                # Use action stage as the flood threshold (lowest level of concern)
                if action:
                    flood_stages[site_no] = float(action)
                elif minor:
                    flood_stages[site_no] = float(minor)
            print(f"  Found flood stages for {len(flood_stages)} stations")
except Exception as e:
    print(f"  Error: {e}")

# Now analyze the data to find flooding days
print("\n" + "="*60)
print("ANALYZING FLOOD CONDITIONS")
print("="*60)

flood_results = {}
dates_in_range = ["2025-04-01", "2025-04-02", "2025-04-03", "2025-04-04",
                  "2025-04-05", "2025-04-06", "2025-04-07"]

for station in stations:
    if station not in flood_stages:
        continue

    flood_stage = flood_stages[station]
    flood_days = 0

    if station in gage_data:
        for date in dates_in_range:
            if date in gage_data[station]:
                gage_height = gage_data[station][date]
                if gage_height >= flood_stage:
                    flood_days += 1
                    print(f"  {station} on {date}: gage={gage_height:.2f} >= flood_stage={flood_stage:.2f} - FLOODING")

    if flood_days > 0:
        flood_results[station] = flood_days

# Summary
print("\n" + "="*60)
print("SUMMARY")
print("="*60)
print(f"Total stations analyzed: {len(stations)}")
print(f"Stations with flood stage data: {len(flood_stages)}")
print(f"Stations with gage height data: {len(gage_data)}")
print(f"Stations that experienced flooding: {len(flood_results)}")

# Write results to CSV
output_file = "/root/output/flood_results.csv"
with open(output_file, 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['station_id', 'flood_days'])
    for station_id, flood_days in sorted(flood_results.items()):
        writer.writerow([station_id, flood_days])

print(f"\nResults written to {output_file}")

if flood_results:
    print("\nStations with flooding:")
    for station_id, flood_days in sorted(flood_results.items()):
        print(f"  {station_id}: {flood_days} days")
else:
    print("\nNo flooding detected in the analyzed stations.")
    print("This could mean:")
    print("  1. No stations exceeded their flood stage during April 1-7, 2025")
    print("  2. Flood stage data was not available for stations with gage data")

