#!/usr/bin/env python3
"""
Analyze USGS streamflow data to find stations that experienced flooding
during April 1-7, 2025.
"""

import requests
import csv
import re
from datetime import datetime

# Read station IDs
with open('/root/data/michigan_stations.txt', 'r') as f:
    stations = [line.strip() for line in f if line.strip()]

print(f"Found {len(stations)} stations to analyze")

# Date range
start_date = "2025-04-01"
end_date = "2025-04-07"
dates_in_range = ["2025-04-01", "2025-04-02", "2025-04-03", "2025-04-04",
                  "2025-04-05", "2025-04-06", "2025-04-07"]

stations_str = ",".join(stations)

# First, let's get flood stage data using the RDB format from USGS
print("\nFetching flood stage data from NWIS...")

flood_stages = {}

# Try getting flood stage info from USGS groundwater levels API or peaks
# The flood stage is often available in the site description or via NWS

# Let's try the USGS Groundwater Watch flood stages via REST
for station in stations:
    try:
        # Try to get peak streamflow data which includes flood stage
        url = f"https://nwis.waterdata.usgs.gov/nwis/peak?site_no={station}&format=rdb"
        resp = requests.get(url, timeout=30, headers={'User-Agent': 'Mozilla/5.0'})
        # This gives historical peaks but not flood stages
    except:
        pass

# Alternative: Get flood stages from NWS AHPS
print("\nFetching flood stages from NWS AHPS...")

# NWS AHPS provides flood stages - let's try individual stations
nws_flood_stages = {}

# Map USGS sites to NWS locations (this would typically come from a lookup)
# Let's try parsing from NWS API
try:
    # Get a sample to see the format
    url = "https://api.water.noaa.gov/nwps/v1/gauges?state=MI"
    resp = requests.get(url, timeout=60, headers={'User-Agent': 'Mozilla/5.0'})
    if resp.status_code == 200:
        data = resp.json()
        if 'gauges' in data:
            for gauge in data['gauges']:
                usgs_id = gauge.get('usgsSiteCode', '')
                if usgs_id in stations:
                    # Get flood categories
                    flood_cats = gauge.get('floodCategories', {})
                    action = flood_cats.get('action', {}).get('stage')
                    minor = flood_cats.get('minor', {}).get('stage')
                    if action:
                        flood_stages[usgs_id] = float(action)
                        print(f"  {usgs_id}: action stage = {action} ft")
                    elif minor:
                        flood_stages[usgs_id] = float(minor)
                        print(f"  {usgs_id}: minor flood stage = {minor} ft")
except Exception as e:
    print(f"  NWS API error: {e}")

print(f"\nFound flood stages for {len(flood_stages)} stations from NWS")

# If we still don't have flood stages, try getting them from individual gauge pages
if len(flood_stages) < 10:
    print("\nTrying to fetch flood stages from NWS gauge API...")
    try:
        # Get list of all NWS gauges in Michigan
        url = "https://api.water.noaa.gov/nwps/v1/gauges?state=MI"
        resp = requests.get(url, timeout=60)
        if resp.status_code == 200:
            data = resp.json()
            gauges = data.get('gauges', [])
            print(f"  Found {len(gauges)} NWS gauges in Michigan")

            for gauge in gauges:
                usgs_id = gauge.get('usgsSiteCode', '')
                lid = gauge.get('lid', '')
                if usgs_id in stations:
                    # Get detailed gauge info
                    try:
                        detail_url = f"https://api.water.noaa.gov/nwps/v1/gauges/{lid}"
                        detail_resp = requests.get(detail_url, timeout=30)
                        if detail_resp.status_code == 200:
                            detail = detail_resp.json()
                            flood_cats = detail.get('floodCategories', {})
                            action = flood_cats.get('action', {}).get('stage')
                            minor = flood_cats.get('minor', {}).get('stage')
                            if action:
                                flood_stages[usgs_id] = float(action)
                                print(f"  {usgs_id}: action stage = {action} ft")
                            elif minor:
                                flood_stages[usgs_id] = float(minor)
                                print(f"  {usgs_id}: minor flood stage = {minor} ft")
                    except:
                        pass
    except Exception as e:
        print(f"  Error: {e}")

print(f"\nTotal flood stages found: {len(flood_stages)}")

# Now fetch gage height data for the date range
print("\nFetching gage height data for April 1-7, 2025...")

# Get instantaneous values for gage height (parameter 00065)
url = f"https://waterservices.usgs.gov/nwis/iv/?format=json&sites={stations_str}&startDT={start_date}&endDT={end_date}&parameterCd=00065&siteStatus=all"

gage_data = {}
try:
    resp = requests.get(url, timeout=120)
    if resp.status_code == 200:
        data = resp.json()
        if 'value' in data and 'timeSeries' in data['value']:
            for ts in data['value']['timeSeries']:
                site_code = ts['sourceInfo']['siteCode'][0]['value']
                if 'values' in ts and len(ts['values']) > 0:
                    values_list = ts['values'][0].get('value', [])
                    if site_code not in gage_data:
                        gage_data[site_code] = {}
                    for v in values_list:
                        date = v['dateTime'][:10]
                        try:
                            val = float(v['value'])
                            # Keep the maximum value per day
                            if date not in gage_data[site_code] or val > gage_data[site_code][date]:
                                gage_data[site_code][date] = val
                        except:
                            pass
        print(f"  Retrieved gage height data for {len(gage_data)} stations")
except Exception as e:
    print(f"  Error: {e}")

# Now analyze the data to find flooding days
print("\n" + "="*60)
print("ANALYZING FLOOD CONDITIONS")
print("="*60)

flood_results = {}

for station in stations:
    if station not in flood_stages:
        continue

    flood_stage = flood_stages[station]
    flood_days = 0

    if station in gage_data:
        for date in dates_in_range:
            if date in gage_data[station]:
                gage_height = gage_data[station][date]
                if gage_height >= flood_stage:
                    flood_days += 1
                    print(f"  {station} on {date}: gage={gage_height:.2f} >= flood_stage={flood_stage:.2f} - FLOODING")

    if flood_days > 0:
        flood_results[station] = flood_days

# Summary
print("\n" + "="*60)
print("SUMMARY")
print("="*60)
print(f"Total stations analyzed: {len(stations)}")
print(f"Stations with flood stage data: {len(flood_stages)}")
print(f"Stations with gage height data: {len(gage_data)}")
print(f"Stations that experienced flooding: {len(flood_results)}")

# Write results to CSV
output_file = "/root/output/flood_results.csv"
with open(output_file, 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['station_id', 'flood_days'])
    for station_id, flood_days in sorted(flood_results.items()):
        writer.writerow([station_id, flood_days])

print(f"\nResults written to {output_file}")

if flood_results:
    print("\nStations with flooding:")
    for station_id, flood_days in sorted(flood_results.items()):
        print(f"  {station_id}: {flood_days} days")
else:
    print("\nNo flooding detected in the analyzed stations for April 1-7, 2025.")
